  },
  "prepTime": "PT30M",
  "recipeCategory": "Dinner, Main course",
  "recipeCuisine": "British",
  "recipeIngredient": [
    "4 small chicken breasts",
    "3 tbsp grated parmesan",
    "100g flour",
    "1 large egg beaten",
    "75g dried breadcrumbs (we used panko)",
    "75ml vegetable oil",
    "300g white cabbage shredded",
    "1 large carrot peeled and grated",
    "6 spring onions sliced diagonally",
    "1 red-skinned apple grated",
    "150g pot natural yogurt",
    "juice ½ lemon",
    "2 tsp English mustard"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToStep",
      "text": "For the coleslaw, mix all the ingredients in a large bowl. Season a little and set aside."
    },
    {
      "@type": "HowToStep",
      "text": "Place a layer of cling film on your work surface and pop the chicken fillets on top. Cover with another piece of cling film and, using a rolling pin, bash the chicken until it is 2-3mm thick.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/1-Flattened-chicken-780c12c.jpg",
        "width": 1000,
        "height": 667
      }
    },
    {
      "@type": "HowToStep",
      "text": "Put the flour on a plate and season, then put the egg on another plate.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/2.-Flour-and-egg-b3da00a.jpg",
        "width": 1000,
        "height": 667
      }
    },
    {
      "@type": "HowToStep",
      "text": "Dip the chicken in the flour to coat, then into the egg.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/4.-Flouring-chicken-b47a30d.jpg",
        "width": 1000,
        "height": 667
      }
    },
    {
      "@type": "HowToStep",
      "text": "Mix together the breadcrumbs and Parmesan in a shallow bowl, then toss the chicken in the mixture to completely coat in the crumbs. Put the chicken on a plate and chill in the fridge until ready to eat if you’re not cooking them straight away.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/6.-Chicken-in-panko-05ff6b9.jpg",
        "width": 1000,
        "height": 667
      }
    },
    {
      "@type": "HowToStep",
      "text": "Heat the oil in a large frying pan over a fairly high heat and cook the chicken schnitzels two at a time.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/8.-Chicken-cooking-f8bfdec.jpg",
        "width": 921,
        "height": 614
      }
    },
    {
      "@type": "HowToStep",
      "text": "Sizzle them for 2-3 mins each side until completely golden, then lift out onto kitchen paper to drain. You can keep them warm in a low oven while you cook the rest. Serve with the coleslaw.",
      "image": {
        "@type": "ImageObject",
        "url": "https://images.immediate.co.uk/production/volatile/sites/30/2025/02/11.-Finished-golden-chicken-4f1c806.jpg",
        "width": 1000,
        "height": 667
      }
    }
  ],
  "recipeYield": 4,
  "totalTime": "PT40M"
}
